#include <cstdio>
#include <cstdlib>
#include <fstream>
#include <iterator>
#include <limits>
#include <stdexcept>
#include "engine/audio/source_adx_sdk_gain.hpp"
namespace {using namespace gf;unsigned checks=0;void check(bool v,const char* why){++checks;if(!v){std::fprintf(stderr,"ADX SDK gain: %s\n",why);std::abort();}}
std::vector<u8> owned_profile(){std::vector<u8> b(2462);store_be32(b.data(),0x47464147);store_be32(b.data()+4,1);store_be16(b.data()+8,963);store_be16(b.data()+10,128);store_be32(b.data()+12,u32(-903));store_be32(b.data()+16,60);store_be16(b.data()+20,0xff64);for(unsigned i=0;i<963;++i){const unsigned value=i<=903?1+32766*i/903:32767+(0xff64-32767)*(i-903)/60;store_be16(b.data()+24+i*2,u16(value));}for(unsigned i=0;i<128;++i){s32 p=i<=63?-s32(i*30/63):i==64?-30:-30-s32((i-64)*874/63);store_be32(b.data()+24+1926+i*4,u32(p));}return b;}
void owned(){check(pcm_scale_q15_clipped(-1,1)==-1&&pcm_scale_q15_clipped(1,32767)==0&&pcm_scale_q15_clipped(-1,32767)==-1,"floor-negative signed Q15, not truncating zero");check(pcm_scale_q15_clipped(32767,65535)==32767&&pcm_scale_q15_clipped(-32768,65535)==-32768&&pcm_scale_q15_clipped(100,-32768)==-100,"shared signedVE/unsignedmix/clamp");auto b=owned_profile();SourceAdxSdkGainProfile p;check(p.load({b.data(),b.size()}),"owned source-shaped profile");for(unsigned n=0;n<2462;++n){SourceAdxSdkGainProfile bad;check(!bad.load({b.data(),n})&&!bad.ready(),"all truncated extents refuse/clear");}u16 v=99;check(p.lookup(-904,&v)&&v==0&&p.lookup(-903,&v)&&v==1&&p.lookup(0,&v)&&v==32767&&p.lookup(60,&v)&&v==0xff64,"raw source threshold/table/cap not pow");check(p.lookup(std::numeric_limits<s32>::min(),&v)&&v==0&&p.lookup(std::numeric_limits<s32>::max(),&v)&&v==0xff64&&!p.lookup(0,nullptr),"lookup boundary/null safety");SourceAdxSdkGainControl c;SourceAdxSdkGainPacket packet;check(!c.request_volume(0)&&!c.update_control(&packet)&&!c.configure(p,SourceAdxSdkOutput(2)),"no unconfigured/output-mode fallback");check(c.configure(p,SourceAdxSdkOutput::Mono)&&!c.configure(p,SourceAdxSdkOutput::Stereo)&&c.update_control(&packet)&&packet.envelope_start==32767&&packet.envelope_delta==0&&!packet.envelope_update&&packet.main_left==32767,"constructor0dB state/no entry reconfigure");u16 target=0;check(p.lookup(-44,&target)&&c.request_volume(-44)&&c.dirty()&&c.update_control(&packet)&&packet.envelope_update&&packet.envelope_start==32767&&packet.target==target&&packet.envelope_delta==(s32(target)-32767)/160&&c.settling(),"volume dirty computes target/ramp");std::array<s16,160> input{};input.fill(10000);std::vector<s64> out;u16 after=0;check(source_adx_sdk_gain_render(packet,input,&out,&after)&&out.size()==320&&after==u16(32767+s32(packet.envelope_delta)*160),"active source-frame render with distinct residual");check(c.update_control(&packet)&&packet.envelope_update&&packet.envelope_start==target&&packet.envelope_delta==0&&!c.settling(),"next control corrects residual to exact old target");check(c.request_volume(-31)&&c.request_volume(-19)&&c.update_control(&packet)&&p.lookup(-19,&v)&&packet.target==v,"latest pending volume wins, no intermediate ramp execution");check(c.request_volume(500)&&c.requested_volume()==0&&c.request_volume(std::numeric_limits<s32>::min())&&c.requested_volume()==-999,"source signed SDK clamp");auto keep=out;u16 sentinel=77;check(!source_adx_sdk_gain_render(packet,std::span<const s16>(input).first(159),&out,&sentinel)&&out==keep&&sentinel==77,"wrong frame extent leaves output/state alone");auto bad=packet;bad.envelope_delta=-32768;check(!source_adx_sdk_gain_render(bad,input,&out)&&out==keep,"unqualified envelope wrap refuses without partial output");bad=packet;bad.main_left=65535;check(!source_adx_sdk_gain_render(bad,input,&out),"fixed-mono dry route not generic positive-gain mixer");check(!source_adx_sdk_gain_render(packet,input,nullptr),"null output");std::printf("Source SDK ADX gain owned: %u checks PASS; numeric packet/PCM not playback\n",checks);
}
struct Writer {FILE* f;explicit Writer(const std::string& p):f(std::fopen(p.c_str(),"wx")){if(!f)throw std::runtime_error("exclusive SDK gain wire");}void word(u32 x){u8 b[4];store_be32(b,x);if(std::fwrite(b,1,4,f)!=4)throw std::runtime_error("gain word");}void sample(s16 x){u8 b[2];store_be16(b,std::bit_cast<u16>(x));if(std::fwrite(b,1,2,f)!=2)throw std::runtime_error("gain PCM");}void close(){if(std::fclose(f))throw std::runtime_error("gain close");}};
std::vector<u8> read(const std::string& p){std::ifstream f(p,std::ios::binary);if(!f)throw std::runtime_error("gain source input");return {std::istreambuf_iterator<char>(f),{}};}
void source(const std::string& home,const std::string& base){auto file=read(home+"/adx-sdk-gain-art-v1/sdk-gain.gfag");SourceAdxSdkGainProfile p;check(p.load({file.data(),file.size()}),"actual volume/pan profile");Writer lookup(base+".lookup");for(s32 value=-1200;value<=100;++value){u16 gain=0;check(p.lookup(value,&gain),"bounded actual lookup");lookup.word(u32(value));lookup.word(gain);}lookup.close();Writer steady(base+".steady");u64 input_cases=0;for(unsigned mode=0;mode<2;++mode)for(s32 units:{-44,-31,-19,-9,0}){SourceAdxSdkGainControl c;SourceAdxSdkGainPacket packet;check(c.configure(p,SourceAdxSdkOutput(mode))&&c.request_volume(units)&&c.update_control(&packet)&&c.update_control(&packet)&&packet.envelope_delta==0,"settled fixed-source route");for(u32 value:{u32(mode),u32(units),u32(packet.envelope_start),u32(packet.main_left),u32(packet.main_right)})steady.word(value);for(unsigned start=0;start<65536;start+=160){std::array<s16,160> input{};const unsigned count=std::min(160u,65536-start);for(unsigned i=0;i<count;++i)input[i]=std::bit_cast<s16>(u16(start+i));std::vector<s64> out;check(source_adx_sdk_gain_render(packet,input,&out),"all signed16 inputs through same two-stage kernel");for(unsigned i=0;i<count;++i){steady.sample(s16(out[i*2]/65536));steady.sample(s16(out[i*2+1]/65536));++input_cases;}}}steady.close();auto retained=read(home+"/guide-voice-tests-v1/normal.60.48000");Writer ramp(base+".ramp");for(unsigned mode=0;mode<2;++mode){SourceAdxSdkGainControl c;check(c.configure(p,SourceAdxSdkOutput(mode)),"source frame route");for(unsigned frame=0;frame<20;++frame){if(frame==1)c.request_volume(-44);if(frame==4){c.request_volume(-31);c.request_volume(-19);}if(frame==5)c.request_volume(-9);if(frame==6)c.request_volume(0);if(frame==8)c.request_volume(-960);if(frame==10)c.request_volume(-999);if(frame==11)c.request_volume(5);if(frame==12||frame==13)c.request_volume(-44);if(frame==15)c.request_volume(std::numeric_limits<s32>::min());if(frame==17||frame==18)c.request_volume(0);SourceAdxSdkGainPacket packet;check(c.update_control(&packet),"explicit source MIX update, not device/game tick");std::array<s16,160> mono{};for(unsigned i=0;i<160;++i)mono[i]=std::bit_cast<s16>(load_be16(retained.data()+((mode*20+frame)*160+i)*4));std::vector<s64> stereo;u16 after=0;check(source_adx_sdk_gain_render(packet,mono,&stereo,&after),"retained source PCM used as numeric mono INPUT, not actual SRC clock");for(u32 value:{mode,frame,u32(c.requested_volume()),u32(packet.control_serial),u32(packet.envelope_start),u32(u16(packet.envelope_delta)),u32(packet.target),u32(packet.main_left),u32(packet.main_right),u32(packet.envelope_update),u32(c.settling()),u32(after)})ramp.word(value);for(auto value:stereo)ramp.sample(s16(value/65536));}}ramp.close();std::printf("Source SDK ADX gain: %llu signed-input/route cases, 40 control packets; retained PCM DATA only/no SDK stream-phase ACK\n",static_cast<unsigned long long>(input_cases));
}
}
int main(int argc,char** argv){owned();if(argc==3)source(argv[1],argv[2]);else if(argc!=1)return 2;return 0;}
